n\t--ps-text-disabled: #7a7a7a;\n\t--ps-select: #3f689a;\n\t--ps-select-light: #557fb4;\n\t--ps-hover: #5f5f5f;\n\t--ps-font: 'Segoe UI', Tahoma, 'DejaVu Sans', Arial, sans-serif;\n\n\t/* miniPaint variables (dialogs, widgets) */\n\t--background: #535353;\n\t--text-color: #e3e3e3;\n\t--text-color-muted: #a8a8a8;\n\t--section-background-color: #424242;\n\t--area-background-color: #535353;\n\t--block-background-color: #535353;\n\t--header-background-color: #424242;\n\t--button-background-color: #5a5a5a;\n\t--button-background-color-hover: #6a6a6a;\n\t--button-background-color-active: #3f689a;\n\t--button-shadow-color: rgba(0, 0, 0, 0.35);\n\t--button-text-color-active: #ffffff;\n\t--button-border-radius: 2px;\n\t--button-toggle-background-color: #444;\n\t--button-toggle-background-color-hover: #4c4c4c;\n\t--input-background-color: #3a3a3a;\n\t--input-background-color-hover: #404040;\n\t--input-text-color: #ececec;\n\t--input-border-color: #262626;\n\t--input-border-color-active: #6e9bd6;\n\t--input-border-radius: 1px;\n\t--input-group-border-color: #2f2f2f;\n\t--menu-background-color: #535353;\n\t--menu-text-color: #e3e3e3;\n\t--background-color-active: #3f689a;\n\t--background-color-hover: #5f5f5f;\n\t--text-color-active: #ffffff;\n\t--border-color: #2b2b2b;\n\t--scrollbar-track-color: #474747;\n\t--scrollbar-thumb-color: #6b6b6b;\n\t--menu-icons-filter: invert(0.88);\n\n\t--menu-dropdown-background-color: #f0f0f0;\n\t--menu-dropdown-border-color: #979797;\n\t--menu-dropdown-text-color: #000000;\n\t--menu-dropdown-text-muted-color: #6d6d6d;\n\t--menu-dropdown-hover-background-color: #cfe3fb;\n\t--menu-dropdown-hover-text-color: #000000;\n\t--menu-dropdown-divider-color: #d7d7d7;\n\n\tmargin: 0;\n\tbackground: var(--ps-pasteboard);\n\tcolor: var(--ps-text);\n\tfont-family: var(--ps-font);\n\tfont-size: 11px;\n\toverflow: hidden;\n\t-webkit-user-select: none;\n\tuser-select: none;\n}\nbody.theme-cs6 input, body.theme-cs6 select, body.theme-cs6 button, body.theme-cs6 textarea {\n\tfont-family: var(--ps-font);\n}\n\n/* ========== frame grid ===================================================== */\n\n.ps_app {\n\tposition: fixed;\n\tinset: 0;\n\tdisplay: grid;\n\tgrid-template-rows: 22px 34px minmax(0, 1fr) 21px;\n\tgrid-template-columns: 100%;\n\tbackground: var(--ps-panel);\n\tmin-width: 760px;\n}\n.ps_app > .ps_menubar { grid-area: 1 / 1 / 2 / 2; }\n.ps_app > .ps_options { grid-area: 2 / 1 / 3 / 2; }\n.ps_app > .ps_body { grid-area: 3 / 1 / 4 / 2; }\n.ps_app > .ps_bottombar { grid-area: 4 / 1 / 5 / 2; }\n.ps_app.screen_full .ps_menubar,\n.ps_app.hide_panels .ps_options,\n.ps_app.screen_full .ps_options,\n.ps_options.closed {\n\tdisplay: none;\n}\n.ps_app.screen_full { grid-template-rows: 0 0 minmax(0, 1fr) 0; }\n.ps_app.screen_full .ps_bottombar { display: none; }\n.ps_app.hide_panels { grid-template-rows: 22px 0 minmax(0, 1fr) 21px; }\n.ps_app.screen_full.hide_panels { grid-template-rows: 0 0 minmax(0, 1fr) 0; }\n.ps_app:has(.ps_options.closed) { grid-template-rows: 22px 0 minmax(0, 1fr) 21px; }\n\n.ps_body {\n\tdisplay: flex;\n\tmin-height: 0;\n\tborder-top: 1px solid var(--ps-border);\n}\n\n/* ========== menu bar ======================================================= */\n\n.ps_menubar {\n\tdisplay: flex;\n\talign-items: stretch;\n\tbackground: linear-gradient(#5a5a5a, #4d4d4d);\n\tborder-bottom: 1px solid #3a3a3a;\n\tposition: relative;\n\tz-index: 100;\n}\n.ps_logo {\n\twidth: 22px;\n\theight: 18px;\n\tmargin: 2px 6px 0 6px;\n\tborder-radius: 2px;\n\tbackground: linear-gradient(#1d4e7c, #0b2a4a);\n\tborder: 1px solid #5f97cf;\n\tbox-sizing: border-box;\n\tcolor: #9fd5ff;\n\tfont: bold 10px/16px Arial, sans-serif;\n\ttext-align: center;\n\tletter-spacing: -0.3px;\n}\nbody.theme-cs6 .main_menu {\n\tposition: static;\n\tflex: 1;\n}\nbody.theme-cs6 .main_menu > ul.menu_bar {\n\theight: 22px;\n\tpadding-left: 0;\n\tbackground: transparent;\n}\nbody.theme-cs6 .main_menu > ul.menu_bar > li > a {\n\tfont-size: 12px;\n\tpadding: 0 7px;\n\tcolor: #e8e8e8;\n}\nbody.theme-cs6 .main_menu > ul.menu_bar > li > a:hover {\n\tbackground: #6a6a6a;\n\tcolor: #fff;\n}\nbody.theme-cs6 .main_menu > ul.menu_bar > li > a[aria-expanded=\"true\"] {\n\tbackground: #f0f0f0;\n\tcolor: #000;\n}\nbody.theme-cs6 .main_menu > ul.menu_bar > li > a:focus {\n\tbox-shadow: none;\n}\n\n/* dropdowns: Windows-native light menus, as CS6 draws them on Windows */\nbody.theme-cs6 .menu_dropdown {\n\tdisplay: flex;\n\tflex-direction: column;\n\tposition: fixed;\n\tlist-style: none;\n\tmargin: 0;\n\tpadding: 2px;\n\tmin-width: 180px;\n\tmax-height: calc(100vh - 30px);\n\toverflow-y: auto;\n\toverflow-x: hidden;\n\tbackground: #f0f0f0;\n\tborder: 1px solid #979797;\n\tbox-shadow: 3px 3px 4px rgba(0, 0, 0, 0.45);\n\tz-index: 2000;\n\tfont-family: var(--ps-font);\n}\nbody.theme-cs6 .main_menu > ul.menu_dropdown {\n\tbox-shadow: 3px 3px 4px rgba(0, 0, 0, 0.45);\n\tbackground: #f0f0f0;\n}\nbody.theme-cs6 .menu_dropdown > li {\n\tpadding: 0;\n\tlist-style: none;\n}\nbody.theme-cs6 .menu_dropdown > li > hr {\n\tborder: none;\n\tborder-top: 1px solid #d7d7d7;\n\tborder-bottom: 1px solid #ffffff;\n\tmargin: 3px 2px 3px 28px;\n\tbackground: none;\n}\nbody.theme-cs6 .menu_dropdown > li > a {\n\tdisplay: flex;\n\talign-items: center;\n\tposition: relative;\n\theight: 22px;\n\tline-height: 22px;\n\tpadding: 0 22px 0 0;\n\tfont-size: 12px;\n\tcolor: #000;\n\ttext-decoration: none;\n\tborder: 1px solid transparent;\n\tborder-radius: 2px;\n\twhite-space: nowrap;\n\tcursor: default;\n}\nbody.theme-cs6 .menu_dropdown > li > a .check {\n\twidth: 26px;\n\tflex: none;\n\ttext-align: center;\n\tfont-size: 11px;\n}\nbody.theme-cs6 .menu_dropdown > li > a .name {\n\tflex: 1;\n}\nbody.theme-cs6 .menu_dropdown > li > a .shortcut {\n\tmargin-left: 34px;\n\tpadding: 0;\n\tfont-size: 12px;\n\tcolor: inherit;\n\topacity: 1;\n}\nbody.theme-cs6 .menu_dropdown > li > a:hover,\nbody.theme-cs6 .menu_dropdown > li > a:focus,\nbody.theme-cs6 .menu_dropdown > li > a[aria-expanded=\"true\"] {\n\tbackground: linear-gradient(#e8f1fc, #d6e6fb);\n\tborder-color: #aeccf1;\n\tcolor: #000;\n\tbox-shadow: none;\n\toutline: none;\n}\nbody.theme-cs6 .menu_dropdown > li > a.disabled,\nbody.theme-cs6 .menu_dropdown > li > a.disabled:hover {\n\tcolor: #8d8d8d;\n\tbackground: transparent;\n\tborder-color: transparent;\n}\nbody.theme-cs6 .menu_dropdown > li > a.disabled:hover {\n\tbackground: #e5e5e5;\n\tborder-color: #dadada;\n}\nbody.theme-cs6 .menu_dropdown > li > a[aria-haspopup=\"true\"]::after {\n\tcontent: \"\";\n\tposition: absolute;\n\tright: 8px;\n\ttop: 7px;\n\twidth: 0;\n\theight: 0;\n\tborder-top: 4px solid transparent;\n\tborder-bottom: 4px solid transparent;\n\tborder-left: 4px solid currentColor;\n\ttransform: none;\n\tcolor: inherit;\n}\nbody.theme-cs6 .menu_dropdown .ps_menu_icon {\n\tmargin-right: 8px;\n\tcolor: #222;\n\tflex: none;\n}\nbody.theme-cs6 .menu_dropdown .sr_only { display: none; }\n\n/* tool flyout: CS6 draws it dark, like the panels */\nbody.theme-cs6 .menu_dropdown.ps_flyout {\n\tbackground: var(--ps-panel);\n\tborder: 1px solid #262626;\n\tpadding: 1px;\n\tmin-width: 0;\n}\nbody.theme-cs6 .menu_dropdown.ps_flyout > li > a {\n\tcolor: var(--ps-text);\n\theight: 24px;\n\tline-height: 24px;\n\tpadding-right: 12px;\n\tborder-radius: 0;\n}\nbody.theme-cs6 .menu_dropdown.ps_flyout > li > a .check { width: 16px; font-size: 7px; }\nbody.theme-cs6 .menu_dropdown.ps_flyout .ps_menu_icon { color: #ddd; margin-right: 6px; }\nbody.theme-cs6 .menu_dropdown.ps_flyout > li > a:hover {\n\tbackground: var(--ps-select);\n\tborder-color: var(--ps-select);\n\tcolor: #fff;\n}\nbody.theme-cs6 .menu_dropdown.ps_flyout > li > a.disabled { color: #8a8a8a; }\nbody.theme-cs6 .menu_dropdown.ps_flyout > li > a.disabled .ps_menu_icon { color: #7d7d7d; }\nbody.theme-cs6 .menu_dropdown.ps_flyout > li > a.disabled:hover { background: transparent; border-color: transparent; }\n\n/* ========== options bar =========================================